func TestBackend_Exists(t *testing.T) {
	type fields struct {
		namespace   string
		replicaName string
		objects     []runtime.Object
	}

	tests := []struct {
		name    string
		fields  fields
		want    bool
		wantErr bool
	}{
		{
			name: "secret does not exist",
			fields: fields{
				objects:     nil,
				namespace:   "test",
				replicaName: "agent-0",
			},
			want:    false,
			wantErr: false,
		},
		{
			name: "secret exists",
			fields: fields{
				objects: []runtime.Object{
					newSecret("agent-0-state", "test", nil),
				},
				namespace:   "test",
				replicaName: "agent-0",
			},
			want:    true,
			wantErr: false,
		},
		{
			name: "secret exists but generates an error because KUBE_NAMESPACE is not set",
			fields: fields{
				objects:     nil,
				namespace:   "",
				replicaName: "agent-0",
			},
			want:    false,
			wantErr: true,
		},
		{
			name: "secret exists but generates an error because TELEPORT_REPLICA_NAME is not set",
			fields: fields{
				objects: []runtime.Object{
					newSecret("agent-0-state", "test", nil),
				},
				namespace:   "test",
				replicaName: "",
			},
			want:    false,
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// set namespace env variable
			if len(tt.fields.namespace) > 0 {
				t.Setenv(namespaceEnv, tt.fields.namespace)
			}

			// set replicaName env variable
			if len(tt.fields.replicaName) > 0 {
				t.Setenv(teleportReplicaNameEnv, tt.fields.replicaName)
			}

			k8sClient := fake.NewSimpleClientset(tt.fields.objects...)
			b, err := NewWithClient(k8sClient)
			if err != nil && !tt.wantErr {
				require.NoError(t, err)

			} else if err != nil && tt.wantErr {
				return
			}

			require.Equal(t, tt.want, b.Exists(context.TODO()))

		})
	}
}

func newSecret(name, namespace string, data map[string][]byte) *corev1.Secret {
	return &corev1.Secret{
		Type: corev1.SecretTypeOpaque,
		ObjectMeta: v1.ObjectMeta{
			Name:        name,
			Namespace:   namespace,
			Annotations: generateSecretAnnotations(namespace, ""),
		},
		Data: data,
	}
}

func TestBackend_Get(t *testing.T) {
	var (
		payloadTestData = []byte("testData")
		payloadEmpty    = []byte("")
	)

	type fields struct {
		namespace   string
		replicaName string
		objects     []runtime.Object
	}

	type args struct {
		key []byte
	}

	tests := []struct {
		name         string
		fields       fields
		args         args
		want         []byte
		wantNotFound bool
	}{
		{
			name: "secret does not exist",
			fields: fields{
				objects:     nil,
				namespace:   "test",
				replicaName: "agent-0",
			},
			args: args{
				key: backend.Key("ids", "kube", "current"),
			},
			want: nil,

			wantNotFound: true,
		},
		{
			name: "secret exists and key is present",
			args: args{
				key: backend.Key("ids", "kube", "current"),
			},
			fields: fields{
				objects: []runtime.Object{
					newSecret(
						"agent-0-state",
						"test",
						map[string][]byte{
							backendKeyToSecret(backend.Key("ids", "kube", "current")): payloadTestData,
						},
					),
				},
				namespace:   "test",
				replicaName: "agent-0",
			},
			want: payloadTestData,
		},
		{
			name: "secret exists and key is present but empty",
			args: args{
				key: backend.Key("ids", "kube", "current"),
			},
			fields: fields{
				objects: []runtime.Object{
					newSecret(
						"agent-0-state",
						"test",
						map[string][]byte{
							backendKeyToSecret(backend.Key("ids", "kube", "current")): payloadEmpty,
						},
					),
				},
				namespace:   "test",
				replicaName: "agent-0",
			},
			want:         nil,
			wantNotFound: true,
		},
		{
			name: "secret exists but key not present",
			args: args{
				key: backend.Key("ids", "kube", "replacement"),
			},
			fields: fields{
				objects: []runtime.Object{
					newSecret(
						"agent-0-state",
						"test",
						map[string][]byte{
							backendKeyToSecret(backend.Key("ids", "kube", "current")): payloadTestData,
						},
					),
				},
				namespace:   "test",
				replicaName: "agent-0",
			},
			want:         nil,
			wantNotFound: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if len(tt.fields.namespace) > 0 {
				t.Setenv(namespaceEnv, tt.fields.namespace)
			}

			if len(tt.fields.replicaName) > 0 {
				t.Setenv(teleportReplicaNameEnv, tt.fields.replicaName)
			}

			k8sClient := fake.NewSimpleClientset(tt.fields.objects...)
			b, err := NewWithClient(k8sClient)
			require.NoError(t, err)

			got, err := b.Get(context.TODO(), tt.args.key)
			if (err != nil) && (!trace.IsNotFound(err) || !tt.wantNotFound) {
				require.NoError(t, err)
				return
			} else if (err != nil) && trace.IsNotFound(err) && tt.wantNotFound {
				return
			}
			require.Equal(t, got.Value, tt.want)
		})
	}
}

